(() => {
  'use strict';

  const Store = window.FestacolSessionStore;
  const Data = window.FestacolQuestionData;
  const Engine = window.FestacolAssessmentEngine;
  const Proctor = window.FestacolProctorPolicy;
  const root = document.getElementById('app');
  if (!Store || !Data || !Engine || !root) throw new Error('Festacol examination dependencies are unavailable.');

  const esc = (value) => String(value ?? '').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');
  const icon = (path, cls='h-4 w-4 shrink-0') => `<svg class="${cls}" aria-hidden="true" viewBox="0 0 24 24" fill="none"><path stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="${path}"/></svg>`;
  const I = Object.freeze({
    left:'M5 12h14M5 12l4-4m-4 4 4 4', right:'M19 12H5m14 0-4 4m4-4-4-4',
    flag:'M5 14v7M5 4.971v9.541c5.6-5.538 8.4 2.64 14-.086v-9.54C13.4 7.61 10.6-.568 5 4.97Z',
    shield:'M9.5 11.5 11 13l4-3.5M12 20a16.405 16.405 0 0 1-5.092-5.804A16.694 16.694 0 0 1 5 6.666L12 4l7 2.667a16.695 16.695 0 0 1-1.908 7.529A16.406 16.406 0 0 1 12 20Z',
    check:'m9 12 2 2 4-4M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18Z',
    info:'M12 17v-6m0-4h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',
    warn:'M12 9v4m0 4h.01M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0Z',
    list:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01', close:'M6 18 18 6M6 6l12 12',
    review:'M15 4h3a1 1 0 0 1 1 1v15a1 1 0 0 1-1 1H6a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1h3m0 3h6m-6 7 2 2 4-4m-5-9v4h4V3h-4Z'
  });
  const C = Object.freeze({
    primary:'inline-flex min-h-11 items-center justify-center gap-2 rounded-lg bg-gray-900 px-5 py-2.5 text-sm font-semibold text-white transition-colors duration-200 hover:bg-gray-800 focus:outline-none focus:ring-4 focus:ring-gray-300 disabled:cursor-not-allowed disabled:opacity-50 motion-reduce:transition-none',
    secondary:'inline-flex min-h-11 items-center justify-center gap-2 rounded-lg border border-gray-300 bg-white px-5 py-2.5 text-sm font-semibold text-gray-900 transition-colors duration-200 hover:bg-gray-100 focus:outline-none focus:ring-4 focus:ring-gray-200 disabled:cursor-not-allowed disabled:opacity-50 motion-reduce:transition-none',
    quiet:'inline-flex min-h-11 items-center justify-center gap-2 rounded-lg px-4 py-2.5 text-sm font-medium text-gray-700 transition-colors duration-200 hover:bg-gray-100 focus:outline-none focus:ring-4 focus:ring-gray-200 motion-reduce:transition-none',
    field:'block min-h-11 w-full rounded-lg border border-gray-300 bg-gray-50 p-2.5 text-base text-gray-900 placeholder:text-gray-400 focus:border-gray-900 focus:ring-gray-900',
    card:'rounded-xl border border-gray-200 bg-white shadow-sm'
  });

  let session, data, paper=[], profile, candidateHash='', state=null, timer=null, lastTick=Date.now();
  const token = new URL(location.href).searchParams.get('session');
  const portalHref = (page='home') => `./student.html?page=${encodeURIComponent(page)}`;
  const afterRender = () => queueMicrotask(() => window.initFlowbite?.());
  const effectiveStatus = () => session.status !== 'open' ? session.status : session.startsAt && Date.now() < session.startsAt ? 'scheduled' : session.endsAt && Date.now() > session.endsAt ? 'closed' : 'open';
  const formatTime = (seconds) => { const n=Math.max(0,Math.ceil(Number(seconds)||0)), h=Math.floor(n/3600), m=Math.floor((n%3600)/60), s=n%60; return h ? `${h}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}` : `${m}:${String(s).padStart(2,'0')}`; };
  const pageBrand = () => `<a href="${portalHref()}" class="inline-flex items-center gap-3 rounded-lg focus:outline-none focus:ring-4 focus:ring-gray-200"><span class="grid h-10 w-10 place-items-center rounded-lg bg-gray-900 font-display text-sm font-extrabold text-white">F</span><span><strong class="block text-sm font-semibold text-gray-950">Festacol</strong><span class="block text-xs text-gray-500">Student examination</span></span></a>`;
  const alert = (tone,title,detail,id='') => { const t=tone==='danger'?'border-red-200 bg-red-50 text-red-800':tone==='warning'?'border-amber-200 bg-amber-50 text-amber-800':tone==='success'?'border-emerald-200 bg-emerald-50 text-emerald-800':'border-gray-200 bg-gray-50 text-gray-700'; const i=tone==='warning'||tone==='danger'?I.warn:tone==='success'?I.check:I.info; return `<div ${id?`id="${id}"`:''} class="flex items-start gap-3 rounded-lg border p-4 text-sm ${t}" role="alert">${icon(i)}<div><span class="font-semibold">${esc(title)}</span><p class="mt-1 leading-6">${esc(detail)}</p></div></div>`; };
  const fatal = (eyebrow,title,detail,action='') => { stopTimer(); root.innerHTML=`<main class="min-h-dvh bg-gray-50 p-4 sm:p-8"><div class="mx-auto grid min-h-[calc(100dvh-4rem)] max-w-5xl overflow-hidden rounded-2xl border border-gray-200 bg-white shadow-sm lg:grid-cols-[.8fr_1.2fr]"><section class="flex flex-col justify-between border-b border-gray-200 bg-gray-50 p-6 sm:p-8 lg:border-b-0 lg:border-r"><div>${pageBrand()}</div><div class="mt-12"><span class="text-xs font-semibold uppercase tracking-wide text-gray-500">${esc(eyebrow)}</span><p class="mt-3 max-w-sm text-sm leading-6 text-gray-600">Secure school examination workspace.</p></div></section><section class="flex items-center p-6 sm:p-10"><div class="w-full"><h1 class="font-display text-2xl font-bold text-gray-950 sm:text-3xl">${esc(title)}</h1><p class="mt-3 text-sm leading-6 text-gray-600">${esc(detail)}</p>${action?`<div class="mt-6">${action}</div>`:''}</div></section></div></main>`; afterRender(); };

  const hydrateExistingAuth = async () => {
    profile = Store.getStudentProfile();
    if (!profile?.studentHash || Store.getStudentAuth() !== profile.studentHash) return false;
    const resetAt = Store.getAttemptResetAt(session.id, Store.getActiveCandidate(session.id));
    if (resetAt && resetAt > Number(profile.updatedAt || 0)) {
      Store.clearStudentAuth();
      Store.clearActiveCandidate(session.id);
      return false;
    }
    candidateHash = Store.getActiveCandidate(session.id);
    if (!candidateHash && profile.firstName && profile.lastName) {
      candidateHash = await Engine.candidateHash(session.id, profile.firstName, profile.lastName);
      Store.setActiveCandidate(session.id, candidateHash);
    }
    return Boolean(candidateHash);
  };
  const authenticate = async (firstName,lastName) => {
    const credentials=Engine.candidateCredentials(firstName,lastName);
    const studentHash=await Engine.studentHash(credentials.firstName,credentials.lastName);
    candidateHash=await Engine.candidateHash(session.id,credentials.firstName,credentials.lastName);
    const existing=Store.getStudentState(session.id,candidateHash);
    profile=Store.saveStudentProfile({...credentials,studentHash,candidateHash,currentClassId:existing?.classGroup||session.classGroup,academicSession:session.academicSession});
    Store.setStudentAuth(studentHash);
    Store.setActiveCandidate(session.id,candidateHash);
    return profile;
  };

  const authView = (message='') => { root.innerHTML=`<main class="min-h-dvh bg-gray-50 px-4 py-8 sm:px-6 lg:px-8"><div class="mx-auto grid min-h-[calc(100dvh-4rem)] max-w-6xl overflow-hidden rounded-2xl border border-gray-200 bg-white shadow-sm lg:grid-cols-[minmax(0,1fr)_minmax(420px,.85fr)]"><section class="flex flex-col justify-between border-b border-gray-200 bg-gray-50 p-6 sm:p-8 lg:border-b-0 lg:border-r lg:p-10"><div>${pageBrand()}</div><div class="mt-12"><span class="inline-flex rounded-md bg-gray-900 px-2.5 py-1 text-xs font-medium text-white">Direct examination access</span><h1 class="mt-4 max-w-xl font-display text-3xl font-bold leading-tight text-gray-950 sm:text-4xl">${esc(session.title)}</h1><p class="mt-3 max-w-lg text-sm leading-6 text-gray-600">Sign in with the candidate credentials assigned by the school. You will continue directly to this examination.</p></div></section><section class="flex items-center p-6 sm:p-8 lg:p-10"><form id="student-login-form" class="w-full space-y-5" novalidate><div><p class="text-sm font-semibold text-gray-950">Candidate sign in</p><p class="mt-1 text-sm text-gray-500">${esc(session.classLevel)} · ${esc(Store.getModeLabel(session.mode))}</p></div>${message?alert('danger','Sign-in unsuccessful',message,'login-error'):''}<div><label for="exam-first-name" class="mb-2 block text-sm font-medium text-gray-900">First name</label><input id="exam-first-name" name="firstName" class="${C.field}" autocomplete="given-name" required></div><div><label for="exam-last-name" class="mb-2 block text-sm font-medium text-gray-900">Last name</label><input id="exam-last-name" name="lastName" type="password" class="${C.field}" autocomplete="current-password" required></div><button type="submit" class="${C.primary} w-full">Continue${icon(I.right)}</button></form></section></div></main>`; const form=root.querySelector('#student-login-form'); form.addEventListener('submit',async(e)=>{ e.preventDefault(); const button=form.querySelector('button[type=submit]'); button.disabled=true; button.setAttribute('aria-busy','true'); try{ await authenticate(new FormData(form).get('firstName'),new FormData(form).get('lastName')); await enterAuthenticatedFlow(); }catch(err){ authView(err.message); } }); afterRender(); };

  const briefing = () => { const subjects=(session.subjects||[]).map(code=>Data.subjectByCode(data,code)?.label||code).join(', ') || Store.getModeLabel(session.mode); root.innerHTML=`<main class="min-h-dvh bg-gray-50"><header class="border-b border-gray-200 bg-white"><div class="mx-auto flex max-w-6xl items-center justify-between gap-4 px-4 py-4 sm:px-6">${pageBrand()}<span class="text-xs font-medium text-gray-500">Attempt 1 of 1</span></div></header><div class="mx-auto max-w-4xl p-4 sm:p-6 lg:p-8"><section class="overflow-hidden ${C.card}"><div class="border-b border-gray-200 p-6 sm:p-8"><span class="inline-flex rounded-md bg-gray-100 px-2.5 py-1 text-xs font-medium text-gray-700">Before you begin</span><h1 class="mt-4 font-display text-3xl font-bold text-gray-950">${esc(session.title)}</h1><p class="mt-3 text-sm leading-6 text-gray-600">Read the examination information carefully before starting. Your timer begins only when you select Start examination.</p></div><div class="grid gap-4 border-b border-gray-200 bg-gray-50 p-5 sm:grid-cols-3 sm:p-6"><div><span class="text-xs text-gray-500">Duration</span><strong class="mt-1 block text-sm text-gray-950">${esc(Store.durationLabel(session.durationSeconds))}</strong></div><div><span class="text-xs text-gray-500">Questions</span><strong class="mt-1 block text-sm text-gray-950">${paper.length}</strong></div><div><span class="text-xs text-gray-500">Coverage</span><strong class="mt-1 block text-sm text-gray-950">${esc(subjects)}</strong></div></div><div class="space-y-5 p-6 sm:p-8">${session.instructions?alert('info','School instruction',session.instructions):''}${cameraRequired()?alert('warning','Camera required','This session requires an active camera before the examination can start. The prototype shows a local preview and does not record or upload video.'):''}<ul class="space-y-3 text-sm leading-6 text-gray-700"><li>• Answer each question using the control provided.</li><li>• Use Previous and Next or the question navigator to move through the paper.</li><li>• Flag questions you want to revisit. Submission is final.</li></ul><button type="button" class="${C.primary} w-full sm:w-auto" data-start>Start examination${icon(I.right)}</button></div></section></div></main>`; root.querySelector('[data-start]').addEventListener('click',start); afterRender(); };
  const cameraRequired = () => Boolean(Proctor?.rememberFromUrl?.(session.id,location.href)?.cameraRequired);

  const fillKeys = (q) => { let i=0; return (Array.isArray(q.fillTemplate)?q.fillTemplate:[]).filter(p=>p?.blank).map(p=>String(p.blank===true?`b${i++}`:p.blank)); };
  const responseStatus = (q) => { const r=state?.responses?.[String(q.id)]; if(q.type==='multi'){const n=Array.isArray(r)?r.length:0; return !n?'unanswered':q.requiredSelections&&n!==Number(q.requiredSelections)?'incomplete':'answered';} if(q.type==='fill'||q.type==='fill-multi'){const keys=fillKeys(q), values=r&&typeof r==='object'?r:{}; const n=keys.filter(k=>String(values[k]??'').trim()).length; return !n?'unanswered':n<keys.length?'incomplete':'answered';} if(q.type==='boolean') return r===true||r===false?'answered':'unanswered'; return r!==undefined&&r!==null&&String(r).trim()?'answered':'unanswered'; };
  const counts = () => paper.reduce((a,q)=>(a[responseStatus(q)]++,a),{answered:0,incomplete:0,unanswered:0});
  const statusMeta = (s) => s==='answered'?['Answered','bg-emerald-100 text-emerald-800','border-emerald-300 bg-emerald-50 text-emerald-800']:s==='incomplete'?['Incomplete','bg-amber-100 text-amber-800','border-amber-300 bg-amber-50 text-amber-800']:['Unanswered','bg-gray-100 text-gray-700','border-gray-300 bg-white text-gray-700'];
  const progressMarkup = () => { const x=counts(), percent=paper.length?Math.round(x.answered/paper.length*100):0; const segments=paper.map(q=>`<span class="h-full flex-1 ${responseStatus(q)==='answered'?'bg-gray-900':responseStatus(q)==='incomplete'?'bg-amber-400':'bg-gray-200'}" aria-hidden="true"></span>`).join(''); return `<section class="mb-4 rounded-xl border border-gray-200 bg-white p-4 shadow-sm" aria-label="Examination progress"><div class="mb-2 flex items-center justify-between gap-3"><div><p class="text-sm font-semibold text-gray-900">Paper progress</p><p id="paper-progress-label" class="text-xs text-gray-500">${x.answered} of ${paper.length} answered${x.incomplete?` · ${x.incomplete} incomplete`:''}</p></div><span id="paper-progress-percent" class="text-sm font-semibold text-gray-900">${percent}%</span></div><div id="paper-progress-bar" class="flex h-2.5 w-full gap-px overflow-hidden rounded-full bg-gray-200" role="progressbar" aria-valuemin="0" aria-valuemax="${paper.length}" aria-valuenow="${x.answered}" aria-label="${x.answered} of ${paper.length} questions answered">${segments}</div></section>`; };
  const navigatorButton = (q,index,review=false) => { const s=responseStatus(q), meta=statusMeta(s), current=index===Number(state.currentIndex||0), flagged=state.flagged?.includes(q.id); return `<button type="button" ${review?`data-go-review="${index}"`:`data-go="${index}" data-status="${s}"`} aria-current="${current?'step':'false'}" aria-label="Question ${index+1}, ${s}${flagged?', flagged':''}" class="relative grid min-h-11 min-w-11 place-items-center rounded-lg border text-sm font-semibold transition-colors duration-200 focus:outline-none focus:ring-4 focus:ring-gray-200 motion-reduce:transition-none ${current&&!review?'border-gray-900 bg-gray-900 text-white':meta[2]}">${index+1}${flagged?'<span class="absolute right-1 top-1 h-2 w-2 rounded-full bg-amber-500"></span>':''}</button>`; };

  const renderTriangle = () => `<figure class="mb-6 overflow-hidden rounded-lg border border-gray-200 bg-gray-50 p-4"><svg class="mx-auto h-auto w-full max-w-xl text-gray-900" viewBox="0 0 560 280" role="img" aria-labelledby="triangle-title triangle-desc"><title id="triangle-title">Triangle ABC</title><desc id="triangle-desc">Triangle ABC with angle A equal to 50 degrees and angle B equal to 65 degrees.</desc><path d="M80 230 L480 230 L300 45 Z" fill="none" stroke="currentColor" stroke-width="4"/><text x="62" y="255" font-size="22" fill="currentColor">A</text><text x="488" y="255" font-size="22" fill="currentColor">B</text><text x="292" y="32" font-size="22" fill="currentColor">C</text><text x="120" y="215" font-size="20" fill="currentColor">50°</text><text x="410" y="215" font-size="20" fill="currentColor">65°</text></svg><figcaption class="mt-2 text-center text-xs text-gray-500">Diagram for this question</figcaption></figure>`;
  const renderTable = (table) => !table?.headers||!Array.isArray(table.rows)?'':`<div class="mb-6 overflow-x-auto rounded-lg border border-gray-200"><table class="w-full min-w-[420px] text-left text-sm text-gray-700"><thead class="bg-gray-100 text-xs uppercase text-gray-700"><tr>${table.headers.map(h=>`<th class="px-4 py-3">${esc(h)}</th>`).join('')}</tr></thead><tbody class="divide-y divide-gray-200 bg-white">${table.rows.map(row=>`<tr>${row.map(cell=>`<td class="px-4 py-3">${esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const option = (q,value,label,index,checked,type='radio') => `<label class="flex min-h-14 cursor-pointer items-center gap-3 rounded-lg border p-4 text-sm font-medium transition-colors duration-200 focus-within:ring-4 focus-within:ring-gray-200 motion-reduce:transition-none ${checked?'border-gray-900 bg-gray-50 text-gray-950':'border-gray-200 bg-white text-gray-900 hover:bg-gray-50'}"><input class="h-4 w-4 border-gray-300 bg-gray-100 text-gray-900 focus:ring-2 focus:ring-gray-500" type="${type}" name="q-${q.id}" value="${esc(value)}" ${checked?'checked':''}><span class="grid h-7 w-7 shrink-0 place-items-center rounded-md border border-gray-300 bg-white text-xs font-semibold text-gray-700">${label||String.fromCharCode(65+index)}</span><span>${esc(value)}</span></label>`;
  const renderControl = (q) => { const r=state.responses?.[String(q.id)]; if(q.type==='single') return `<fieldset class="grid gap-3"><legend class="sr-only">Choose one answer</legend>${(q.options||[]).map((o,i)=>option(q,o,'',i,r===o)).join('')}</fieldset>`; if(q.type==='multi') return `<fieldset class="grid gap-3"><legend class="sr-only">Choose the required answers</legend>${q.requiredSelections?`<p class="text-xs font-medium text-gray-500">Select ${q.requiredSelections} answer${Number(q.requiredSelections)===1?'':'s'}.</p>`:''}<div id="selection-limit" class="hidden">${alert('warning','Selection limit reached',`Choose no more than ${q.requiredSelections} answers.`)}</div>${(q.options||[]).map((o,i)=>option(q,o,'',i,Array.isArray(r)&&r.includes(o),'checkbox')).join('')}</fieldset>`; if(q.type==='boolean') return `<fieldset class="grid gap-3 sm:grid-cols-2"><legend class="sr-only">True or false</legend>${[[true,'True'],[false,'False']].map(([v,l],i)=>option(q,String(v),l,i,r===v)).join('')}</fieldset>`; if(q.type==='fill'||q.type==='fill-multi'){ const values=r&&typeof r==='object'?r:{}; let i=0; const parts=Array.isArray(q.fillTemplate)?q.fillTemplate:[{text:q.prompt},{blank:true}]; return `<div class="rounded-lg border border-gray-200 bg-gray-50 p-4"><div class="flex flex-wrap items-baseline gap-2 text-base leading-9 text-gray-900">${parts.map(part=>{ if(!part?.blank)return `<span>${esc(part?.text||'')}</span>`; const key=String(part.blank===true?`b${i}`:part.blank); i++; return `<span class="inline-block min-w-44"><label class="sr-only" for="fill-${q.id}-${esc(key)}">Answer blank ${i}</label><input id="fill-${q.id}-${esc(key)}" class="${C.field} !min-h-10 !bg-white !py-1.5" data-fill-key="${esc(key)}" value="${esc(values[key]||'')}" autocomplete="off" placeholder="${esc(part.placeholder||'Type answer')}"></span>`; }).join('')}</div></div>`;} return alert('danger','Unsupported question','This response type cannot be displayed.'); };

  const integrityCount = () => (state?.integrityEvents || []).filter((item) => !['focus-return','fullscreen-enter'].includes(item.type)).length;
  const updateChrome = () => { const t=document.getElementById('exam-timer'), box=document.getElementById('exam-timer-box'); if(t)t.textContent=formatTime(state?.remainingSeconds); if(box){const urgent=Number(state?.remainingSeconds)<=300; box.className=urgent?'rounded-lg border border-amber-300 bg-amber-50 px-3 py-2 text-right text-amber-900 motion-safe:animate-pulse':'rounded-lg border border-gray-200 bg-gray-50 px-3 py-2 text-right text-gray-900';} const n=root.querySelector('[data-integrity-count]'); if(n)n.textContent=`Integrity ${integrityCount()}`; };
  const examView = () => { const index=Number(state.currentIndex||0), q=paper[index], sum=counts(), s=responseStatus(q), meta=statusMeta(s), flagged=state.flagged?.includes(q.id); root.innerHTML=`<div class="min-h-dvh bg-gray-50 text-gray-900"><header class="sticky top-0 z-30 border-b border-gray-200 bg-white/95 backdrop-blur"><div class="mx-auto grid max-w-7xl grid-cols-[minmax(0,1fr)_auto] items-center gap-4 px-4 py-3 sm:px-6 lg:grid-cols-[minmax(0,1fr)_auto_auto] lg:px-8"><div class="flex min-w-0 items-center gap-3"><span class="grid h-10 w-10 shrink-0 place-items-center rounded-lg bg-gray-900 text-sm font-bold text-white">F</span><div class="min-w-0"><strong class="block truncate text-sm font-semibold text-gray-950">${esc(session.title)}</strong><span class="block truncate text-xs text-gray-500">${esc(profile.fullName)} · ${esc(session.classLevel)} · Attempt 1 of 1</span></div></div><div class="hidden items-center gap-4 lg:flex"><span class="text-sm text-gray-600">Question <strong class="text-gray-950">${index+1}/${paper.length}</strong></span><span class="text-sm text-gray-600">Answered <strong class="text-gray-950">${sum.answered}</strong></span><span class="inline-flex items-center gap-1.5 rounded-md bg-gray-100 px-2.5 py-1 text-xs font-medium text-gray-700">${icon(I.shield)}<span data-integrity-count>Integrity ${integrityCount()}</span></span></div><div id="exam-timer-box" class="rounded-lg border border-gray-200 bg-gray-50 px-3 py-2 text-right"><span class="block text-xs text-gray-500">Time left</span><strong id="exam-timer" class="font-display text-lg font-bold tabular-nums">${formatTime(state.remainingSeconds)}</strong></div></div></header><main class="mx-auto grid max-w-7xl gap-5 px-4 py-5 sm:px-6 lg:grid-cols-[minmax(0,1fr)_19rem] lg:px-8"><section class="min-w-0">${progressMarkup()}<article data-exam-workspace class="overflow-hidden ${C.card}"><div class="flex flex-wrap items-center justify-between gap-3 border-b border-gray-200 bg-gray-50 px-5 py-4 sm:px-6"><div class="flex items-center gap-3"><span class="grid h-10 w-10 place-items-center rounded-lg bg-gray-900 text-sm font-semibold text-white">${index+1}</span><div><p class="text-xs font-medium uppercase tracking-wide text-gray-500">${esc(q.subject)}</p><p class="text-sm font-medium text-gray-700">${esc(q.label||q.domain||'Examination question')}</p></div></div><div class="flex items-center gap-2"><span class="inline-flex rounded-md px-2.5 py-1 text-xs font-medium ${meta[1]}">${meta[0]}</span><button type="button" class="${C.quiet}" data-flag="${q.id}" aria-pressed="${flagged?'true':'false'}">${icon(I.flag)}${flagged?'Flagged':'Flag for review'}</button></div></div><div class="p-5 sm:p-6 lg:p-8">${q.passage?`<aside class="mb-6 rounded-lg border border-gray-200 bg-gray-50 p-4"><p class="text-xs font-semibold uppercase tracking-wide text-gray-500">Read the passage</p><p class="mt-2 text-sm leading-7 text-gray-700">${esc(q.passage)}</p></aside>`:''}${q.diagram==='triangle'?renderTriangle():''}${q.table?renderTable(q.table):''}<h1 class="max-w-4xl font-display text-xl font-bold leading-8 text-gray-950 sm:text-2xl sm:leading-9">${esc(q.prompt)}</h1>${q.instruction?`<p class="mt-2 text-sm font-medium text-gray-600">${esc(q.instruction)}</p>`:''}<div class="mt-6">${renderControl(q)}</div></div><footer class="flex flex-col gap-3 border-t border-gray-200 p-4 sm:flex-row sm:items-center sm:justify-between sm:p-5"><button type="button" class="${C.secondary} lg:hidden" data-drawer-target="question-drawer" data-drawer-show="question-drawer" data-drawer-placement="right" data-drawer-backdrop="true" aria-controls="question-drawer">${icon(I.list)}Question navigator</button><div class="grid grid-cols-2 gap-2 sm:ml-auto sm:flex"><button type="button" class="${C.secondary}" data-previous ${index===0?'disabled':''}>${icon(I.left)}Previous</button><button type="button" class="${C.primary}" data-next>Next${icon(I.right)}</button></div></footer></article></section><aside id="question-map" class="hidden lg:block"><div class="sticky top-24 ${C.card} p-5"><div class="flex items-start justify-between gap-3"><div><p class="text-sm font-semibold text-gray-900">Question navigator</p><p class="mt-1 text-xs text-gray-500">${sum.answered} answered · ${sum.unanswered} unanswered</p></div><button type="button" class="${C.quiet} !min-h-9 !px-2.5 !py-1.5" data-review>${icon(I.review)}Review</button></div><div class="mt-4 grid grid-cols-5 gap-2">${paper.map(navigatorButton).join('')}</div><button type="button" class="${C.secondary} mt-5 w-full" data-review>${icon(I.review)}Review examination</button></div></aside></main><div id="question-drawer" class="fixed right-0 top-0 z-50 h-screen w-80 translate-x-full overflow-y-auto bg-white p-5 shadow-xl transition-transform duration-300 motion-reduce:transition-none" tabindex="-1" aria-labelledby="question-drawer-label"><div class="flex items-center justify-between"><h2 id="question-drawer-label" class="text-base font-semibold text-gray-900">Question navigator</h2><button type="button" data-drawer-hide="question-drawer" aria-controls="question-drawer" class="inline-flex h-11 w-11 items-center justify-center rounded-lg text-gray-500 hover:bg-gray-100 focus:outline-none focus:ring-4 focus:ring-gray-200">${icon(I.close)}<span class="sr-only">Close navigator</span></button></div><p class="mt-1 text-xs text-gray-500">${sum.answered} of ${paper.length} answered</p><div class="mt-5 grid grid-cols-5 gap-2">${paper.map(navigatorButton).join('')}</div><button type="button" class="${C.primary} mt-6 w-full" data-review>${icon(I.review)}Review examination</button></div></div>`; bindExam(); updateChrome(); afterRender(); };

  const reviewView = () => { recordElapsed(false); persist(); const sum=counts(), issues=sum.unanswered+sum.incomplete; root.innerHTML=`<main class="min-h-dvh bg-gray-50"><header class="border-b border-gray-200 bg-white"><div class="mx-auto flex max-w-7xl items-center justify-between gap-4 px-4 py-4 sm:px-6">${pageBrand()}<div class="text-right"><strong class="block text-sm text-gray-950">${esc(session.title)}</strong><span class="text-xs text-gray-500">Review · timer continues</span></div></div></header><div class="mx-auto max-w-6xl p-4 sm:p-6 lg:p-8"><section class="overflow-hidden ${C.card}"><div class="border-b border-gray-200 p-6 sm:p-8"><span class="inline-flex rounded-md bg-gray-900 px-2.5 py-1 text-xs font-medium text-white">Final review</span><h1 class="mt-4 font-display text-2xl font-bold text-gray-950 sm:text-3xl">Check your paper before submitting.</h1><p class="mt-2 text-sm leading-6 text-gray-600">Return to any question to change an answer or review a flag. Submission cannot be undone.</p><div class="mt-5">${issues?alert('warning','Paper not fully complete',`${sum.unanswered} unanswered · ${sum.incomplete} incomplete.`):alert('success','All questions answered','You can still revisit any question before submitting.')}</div></div><div class="grid gap-3 border-b border-gray-200 bg-gray-50 p-5 sm:grid-cols-4">${[['Answered',sum.answered,'text-emerald-700'],['Incomplete',sum.incomplete,'text-amber-700'],['Unanswered',sum.unanswered,'text-gray-900'],['Flagged',state.flagged?.length||0,'text-gray-900']].map(([l,v,t])=>`<div class="rounded-lg border border-gray-200 bg-white p-4"><span class="text-xs font-medium uppercase tracking-wide text-gray-500">${l}</span><strong class="mt-1 block text-2xl font-bold ${t}">${v}</strong></div>`).join('')}</div><div class="p-5 sm:p-7"><div class="grid grid-cols-5 gap-2 sm:grid-cols-8 md:grid-cols-10">${paper.map((q,i)=>navigatorButton(q,i,true)).join('')}</div><div class="mt-7 flex flex-col-reverse gap-3 sm:flex-row sm:justify-between"><button type="button" class="${C.secondary}" data-back-exam>${icon(I.left)}Back to questions</button><button type="button" class="${C.primary}" data-modal-target="submit-modal" data-modal-toggle="submit-modal">${icon(I.review)}Submit examination</button></div></div></section></div><div id="submit-modal" tabindex="-1" aria-hidden="true" class="fixed left-0 right-0 top-0 z-[100] hidden h-[calc(100%-1rem)] max-h-full w-full items-center justify-center overflow-y-auto overflow-x-hidden p-4 md:inset-0"><div class="relative max-h-full w-full max-w-lg"><div class="relative rounded-xl bg-white shadow-xl"><div class="flex items-start justify-between border-b border-gray-200 p-5"><div><p class="text-sm font-medium text-gray-500">Final action</p><h2 class="mt-1 text-xl font-bold text-gray-950">Submit this examination?</h2></div><button type="button" class="inline-flex h-11 w-11 items-center justify-center rounded-lg text-gray-400 hover:bg-gray-100 focus:outline-none focus:ring-4 focus:ring-gray-200" data-modal-hide="submit-modal">${icon(I.close)}<span class="sr-only">Close submission dialog</span></button></div><div class="space-y-4 p-5">${issues?alert('warning','Some questions need attention',`${sum.unanswered} unanswered · ${sum.incomplete} incomplete.`):alert('success','Paper complete','All questions are answered.')}<p class="text-sm leading-6 text-gray-600">Once submitted, this attempt is locked and cannot be restarted.</p></div><div class="flex flex-col-reverse gap-3 border-t border-gray-200 p-5 sm:flex-row sm:justify-end"><button type="button" class="${C.secondary}" data-modal-hide="submit-modal">Continue reviewing</button><button type="button" class="${C.primary}" data-confirm-submit data-modal-hide="submit-modal">Submit examination</button></div></div></div></div></main>`; bindReview(); afterRender(); };

  const integrity = (type,detail='') => { if(!state?.startedAt||state.submittedAt)return; state.integrityEvents ||= []; state.integrityEvents.push({type,detail,at:Date.now()}); state.integrityEvents=state.integrityEvents.slice(-100); persist(); updateChrome(); };
  const stopTimer = () => { if(timer)clearInterval(timer); timer=null; };
  const persist = () => { if(!state||state.submittedAt)return false; if(Store.isAttemptInvalidated(session.id,candidateHash,state.startedAt)){ showReset(); return false; } state.lastActiveAt=Date.now(); return Store.saveStudentState(session.id,candidateHash,state); };
  const recordElapsed = (autoSubmit=true) => { if(!state?.startedAt||state.submittedAt)return; const now=Date.now(), d=Math.max(0,(now-lastTick)/1000); lastTick=now; state.remainingSeconds=Math.max(0,(Number(state.remainingSeconds)||0)-d); state.elapsedActiveSeconds=(Number(state.elapsedActiveSeconds)||0)+d; const q=paper[state.currentIndex||0]; if(q){state.questionTimings||={}; state.questionTimings[String(q.id)]=(Number(state.questionTimings[String(q.id)])||0)+d;} if(state.remainingSeconds<=0&&autoSubmit){state.remainingSeconds=0; persist(); submit(true);} };
  const startTimer = () => { stopTimer(); lastTick=Date.now(); timer=setInterval(()=>{recordElapsed(); updateChrome(); if(state&&!state.submittedAt)persist();},1000); };
  const locked = () => { const a=Store.findAttempt(session.id,candidateHash); fatal('Attempt complete','This examination has already been submitted.','Attempt 1 of 1 is locked and cannot be restarted.',`<div class="flex flex-wrap gap-3"><a class="${C.primary}" href="${portalHref('analytics')}">Open result & analytics</a><span class="inline-flex min-h-11 items-center rounded-lg border border-gray-200 bg-gray-50 px-4 text-sm font-semibold text-gray-900">Score ${a?.score??0}%</span></div>`); };
  const showReset = () => { stopTimer(); Store.clearStudentAuth(); Store.clearActiveCandidate(session.id); fatal('Attempt reset','This unfinished attempt was reset by an administrator.','Authenticate again with the same assigned credentials to start a fresh attempt.',`<a class="${C.primary}" href="${location.pathname}${location.search}">Authenticate again</a>`); };

  const start = async () => { if(effectiveStatus()!=='open')return; const existing=Store.getStudentState(session.id,candidateHash); if(existing?.startedAt&&!existing.submittedAt){state=existing; paper=Engine.paperForStudent(data,session,candidateHash); startTimer(); examView(); return;} if(Store.hasSubmittedAttempt(session.id,candidateHash)){locked();return;} const resetAt=Store.getAttemptResetAt(session.id,candidateHash); paper=Engine.paperForStudent(data,session,candidateHash); const fingerprint=await Engine.paperFingerprint(session.id,candidateHash,paper), attemptHash=await Engine.attemptHash(session.id,candidateHash,fingerprint), now=Date.now(); state={version:3,candidateHash,studentHash:profile.studentHash,studentName:profile.fullName,firstName:profile.firstName,lastName:profile.lastName,startedAt:Math.max(now,resetAt+1),submittedAt:null,attemptHash,paperFingerprint:fingerprint,questionIds:paper.map(q=>q.id),responses:{},flagged:[],questionTimings:{},currentIndex:0,remainingSeconds:session.durationSeconds,elapsedActiveSeconds:0,integrityEvents:[]}; Store.saveStudentState(session.id,candidateHash,state); Store.recordAttempt({id:attemptHash.slice(0,12),attemptHash,candidateHash,studentHash:profile.studentHash,paperFingerprint:fingerprint,sessionId:session.id,sessionTitle:session.title,firstName:profile.firstName,lastName:profile.lastName,studentName:profile.fullName,classLevel:session.classLevel,classGroup:session.classGroup,academicSession:session.academicSession,mode:session.mode,subjects:session.subjects,startedAt:state.startedAt,remainingSeconds:state.remainingSeconds,questionCount:paper.length,questionIds:state.questionIds}); try{if(session.integrityPolicy.fullscreenPrompt&&document.documentElement.requestFullscreen){await document.documentElement.requestFullscreen();integrity('fullscreen-enter');}}catch{integrity('fullscreen-denied');} startTimer(); examView(); };
  const submit = (automatic=false) => { if(state?.submittedAt)return; recordElapsed(false); state.submittedAt=Date.now(); stopTimer(); const result=Engine.scoreAttempt(paper,state,session); Object.assign(state,{score:result.accuracy,completion:result.completion,paceIndex:result.paceIndex,reasoningIndex:result.reasoningIndex,integrityScore:result.integrityScore,subjectStats:result.subjectStats,placement:result.placement||null,details:result.details}); Store.saveStudentState(session.id,candidateHash,state); Store.recordAttempt({id:state.attemptHash.slice(0,12),attemptHash:state.attemptHash,candidateHash,studentHash:profile.studentHash,paperFingerprint:state.paperFingerprint,sessionId:session.id,sessionTitle:session.title,firstName:profile.firstName,lastName:profile.lastName,studentName:profile.fullName,classLevel:session.classLevel,classGroup:session.classGroup,academicSession:session.academicSession,mode:session.mode,sessionStatus:session.status,sessionEndsAt:session.endsAt,subjects:session.subjects,startedAt:state.startedAt,submittedAt:state.submittedAt,remainingSeconds:state.remainingSeconds,elapsedActiveSeconds:state.elapsedActiveSeconds,answered:counts().answered,questionCount:paper.length,score:result.accuracy,correctCount:result.correctCount,completion:result.completion,paceIndex:result.paceIndex,reasoningIndex:result.reasoningIndex,integrityScore:result.integrityScore,integrityEvents:state.integrityEvents,subjectStats:result.subjectStats,placement:result.placement||null,details:result.details,questionIds:state.questionIds}); root.innerHTML=`<main class="grid min-h-dvh place-items-center bg-gray-50 p-4 sm:p-6"><section class="w-full max-w-2xl overflow-hidden ${C.card}"><div class="border-b border-gray-200 bg-gray-50 p-6 sm:p-8"><span class="inline-flex items-center gap-1.5 rounded-md bg-emerald-100 px-2.5 py-1 text-xs font-medium text-emerald-800">${icon(I.check)}Attempt locked</span><h1 class="mt-4 font-display text-2xl font-bold text-gray-950 sm:text-3xl">${automatic?'Time expired. Your examination was submitted automatically.':'Examination submitted successfully.'}</h1><p class="mt-2 text-sm text-gray-600">Your first and only attempt is now final.</p></div><div class="p-6 sm:p-8"><div class="flex flex-wrap items-end justify-between gap-5"><div><span class="text-xs font-medium uppercase tracking-wide text-gray-500">Score</span><strong class="mt-1 block text-5xl font-bold text-gray-950">${result.accuracy}%</strong></div>${result.placement?`<div class="max-w-xs text-right"><span class="text-xs font-medium uppercase tracking-wide text-gray-500">Recommended stream</span><strong class="mt-1 block text-lg font-semibold text-gray-950">${esc(result.placement.assignedTrack)}</strong><span class="text-xs text-gray-500">${result.placement.confidence}% confidence</span></div>`:''}</div><a href="${portalHref('analytics')}" class="${C.primary} mt-7 w-full">Open student dashboard${icon(I.right)}</a></div></section></main>`; afterRender(); };
  const goTo = (index) => { recordElapsed(false); state.currentIndex=Math.max(0,Math.min(paper.length-1,Number(index)||0)); persist(); examView(); };
  const bindExam = () => { const q=paper[state.currentIndex]; root.querySelectorAll(`input[name="q-${q.id}"]`).forEach(input=>input.addEventListener('change',()=>{ if(q.type==='multi'){const selected=[...root.querySelectorAll(`input[name="q-${q.id}"]:checked`)].map(x=>x.value); if(q.requiredSelections&&selected.length>Number(q.requiredSelections)){input.checked=false;root.querySelector('#selection-limit')?.classList.remove('hidden');return;} state.responses[String(q.id)]=selected;} else if(q.type==='boolean')state.responses[String(q.id)]=input.value==='true'; else state.responses[String(q.id)]=input.value; persist(); examView(); })); root.querySelectorAll('[data-fill-key]').forEach(input=>input.addEventListener('input',()=>{ state.responses[String(q.id)] ||= {}; state.responses[String(q.id)][input.dataset.fillKey]=input.value; persist(); })); root.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>goTo(b.dataset.go))); root.querySelector('[data-flag]')?.addEventListener('click',(ev)=>{const id=Number(ev.currentTarget.dataset.flag);state.flagged||=[];state.flagged=state.flagged.includes(id)?state.flagged.filter(x=>x!==id):[...state.flagged,id];persist();examView();}); root.querySelector('[data-previous]')?.addEventListener('click',()=>goTo(state.currentIndex-1)); root.querySelector('[data-next]')?.addEventListener('click',()=>state.currentIndex>=paper.length-1?reviewView():goTo(state.currentIndex+1)); root.querySelectorAll('[data-review]').forEach(b=>b.addEventListener('click',reviewView)); };
  const bindReview = () => { root.querySelector('[data-back-exam]')?.addEventListener('click',examView); root.querySelectorAll('[data-go-review]').forEach(b=>b.addEventListener('click',()=>goTo(b.dataset.goReview))); root.querySelector('[data-confirm-submit]')?.addEventListener('click',()=>submit(false)); };
  const enterAuthenticatedFlow = async () => { if(effectiveStatus()!=='open'){fatal('Session unavailable','This examination is not open.',effectiveStatus()==='scheduled'?'The session is scheduled but has not started yet.':'The school has closed or disabled this examination.',`<a class="${C.primary}" href="${portalHref()}">Return to student portal</a>`);return;} if(Store.hasSubmittedAttempt(session.id,candidateHash)){locked();return;} state=Store.getStudentState(session.id,candidateHash); if(state?.startedAt&&Store.isAttemptInvalidated(session.id,candidateHash,state.startedAt)){showReset();return;} paper=Engine.paperForStudent(data,session,candidateHash); if(!paper.length){fatal('Paper unavailable','No questions match this exam configuration.','Ask the administrator to review the class, mode and subject coverage.');return;} if(state?.startedAt&&!state.submittedAt){startTimer();examView();return;} briefing(); };

  window.addEventListener('blur',()=>integrity('window-blur'));
  document.addEventListener('visibilitychange',()=>document.hidden?integrity('tab-hidden'):integrity('focus-return'));
  document.addEventListener('fullscreenchange',()=>{if(state?.startedAt&&!state.submittedAt&&!document.fullscreenElement)integrity('fullscreen-exit');});
  ['copy','cut','paste'].forEach(type=>document.addEventListener(type,event=>{if(state?.startedAt&&!state.submittedAt&&session?.integrityPolicy?.clipboardGuard){event.preventDefault();integrity(`clipboard-${type}`);}}));
  window.addEventListener('pagehide',()=>{if(state?.startedAt&&!state.submittedAt){recordElapsed(false);persist();}});

  try { session=Store.resolveSession(Store.decodeSession(token)); } catch(err){ fatal('Invalid exam link','This examination link cannot be opened.',err.message); return; }
  Data.load().then(async payload=>{ data=payload; if(!(await hydrateExistingAuth())){authView();return;} await enterAuthenticatedFlow(); }).catch(err=>fatal('Exam unavailable','The examination could not be prepared.',err.message));
})();
